"""SQLAlchemy ORM model for synthetic satellite telemetry readings."""

from datetime import datetime
from typing import Optional

from sqlalchemy import CheckConstraint, DateTime, Index, Integer, Numeric, String, func
from sqlalchemy.orm import Mapped, mapped_column

from app.db.base import Base


class TelemetryReading(Base):
    """Stores synthetic telemetry samples generated by the backend simulator."""

    __tablename__ = "telemetry_readings"
    __table_args__ = (
        Index("ix_telemetry_timestamp", "timestamp"),
        Index("ix_telemetry_sat_sensor_ts", "satellite_id", "sensor_name", "timestamp"),
        CheckConstraint(
            "sensor_name IN ('battery_voltage', 'temperature', 'roll', 'pitch', 'yaw')",
            name="ck_telemetry_valid_sensor",
        ),
        CheckConstraint(
            "quality_status IN ('NOMINAL', 'FAULT_SIMULATED', 'FROZEN', 'MISSING')",
            name="ck_telemetry_valid_quality",
        ),
    )

    id: Mapped[int] = mapped_column(Integer, primary_key=True, index=True, autoincrement=True)
    satellite_id: Mapped[str] = mapped_column(String(32), nullable=False, index=True)
    sensor_name: Mapped[str] = mapped_column(String(64), nullable=False, index=True)
    sensor_value: Mapped[Optional[float]] = mapped_column(
        Numeric(12, 4, asdecimal=False),
        nullable=True,
    )
    unit: Mapped[str] = mapped_column(String(32), nullable=False)
    timestamp: Mapped[datetime] = mapped_column(
        DateTime(timezone=True),
        nullable=False,
        server_default=func.now(),
    )
    quality_status: Mapped[str] = mapped_column(
        String(32),
        nullable=False,
        default="NOMINAL",
        server_default="NOMINAL",
    )

    def __repr__(self) -> str:
        return (
            f"<TelemetryReading id={self.id} sat={self.satellite_id!r} "
            f"sensor={self.sensor_name!r} value={self.sensor_value} quality={self.quality_status!r}>"
        )
